function getSophosInterceptxTranslation(key, lang) {
    return (sophosinterceptxTranslations[lang] && sophosinterceptxTranslations[lang][key]) ||
           (sophosinterceptxTranslations.en && sophosinterceptxTranslations.en[key]) || null;
}

function applySophosInterceptxTranslations(lang) {
    let count = 0;
    document.querySelectorAll("[data-i18n]").forEach(el => {
        const key = el.getAttribute("data-i18n");
        if (key && (key.startsWith("review.sophos-interceptx.") || key.startsWith("review.common."))) {
            const translation = getSophosInterceptxTranslation(key, lang);
            if (translation) { el.textContent = translation; count++; }
        }
    });
    
}

window.addEventListener("languageChanged", e => setTimeout(() => applySophosInterceptxTranslations(e.detail.language), 200));

if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", () => applySophosInterceptxTranslations(window.i18n?.getCurrentLanguage() || "en"));
} else {
    applySophosInterceptxTranslations(window.i18n?.getCurrentLanguage() || "en");
}
